1	import { useState } from "react";
2	import { useNavigate } from "react-router-dom";
3	import { Check, X, Zap, Shield, HelpCircle, Loader2 } from "lucide-react";
4	import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
5	import { Button } from "@/components/ui/button";
6	import { Badge } from "@/components/ui/badge";
7	import { Switch } from "@/components/ui/switch";
8	import { Label } from "@/components/ui/label";
9	import { Separator } from "@/components/ui/separator";
10	import {
11	  Tooltip,
12	  TooltipContent,
13	  TooltipProvider,
14	  TooltipTrigger,
15	} from "@/components/ui/tooltip";
16	import {
17	  Accordion,
18	  AccordionContent,
19	  AccordionItem,
20	  AccordionTrigger,
21	} from "@/components/ui/accordion";
22	import { PageTransition } from "@/components/shared/PageTransition";
23	import { PRICING_TIERS } from "@/lib/constants";
24	import { useAuth } from "@/contexts/AuthContext";
25	import { useCheckout, useCustomerPortal } from "@/hooks/use-billing";
26	import type { PlanType } from "@/types";
27	import { cn } from "@/lib/utils";
28	
29	const FAQ_ITEMS = [
30	  {
31	    q: "What happens when my 14-day trial ends?",
32	    a: "Your account automatically switches to the Free plan (3 scans/month). You won't be charged unless you explicitly upgrade. All your existing reports remain accessible — we never delete your data.",
33	  },
34	  {
35	    q: "What exactly counts as one scan?",
36	    a: "One scan = one URL analyzed on one device type. Scanning example.com/pricing on desktop counts as 1 scan. If you scan the same URL again (to check improvements), that counts as another scan. Re-scans from the report page also count.",
37	  },
38	  {
39	    q: "How is the CRO score calculated?",
40	    a: "Each of the 7 CRO pillars is scored 0-100 based on specific automated checks (contrast ratios, element positioning, page speed metrics, etc.). Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts. Your overall score is the weighted average.",
41	  },
42	  {
43	    q: "Can I switch between monthly and annual billing?",
44	    a: "Yes. Switch anytime from Settings → Billing. When switching from monthly to annual, we prorate the remaining days on your current cycle as a credit. When switching from annual to monthly, the change takes effect at your next renewal date.",
45	  },
46	  {
47	    q: "Do you offer refunds?",
48	    a: "Yes — 30-day money-back guarantee, no questions asked. If the tool doesn't deliver actionable insights for your specific pages, we'll refund your payment in full. Email support@convertscan.com to request a refund.",
49	  },
50	  {
51	    q: "Is my website data secure?",
52	    a: "We take screenshots and scrape publicly visible page content — the same information any visitor to your site would see. We don't access your CMS, analytics, or any private data. All data is encrypted (TLS 1.3 in transit, AES-256 at rest) and stored on SOC 2 compliant infrastructure.",
53	  },
54	];
55	
56	const COMPARISON_ROWS = [
57	  { feature: "Page scans per month", starter: "5", growth: "25", pro: "Unlimited", agency: "Unlimited" },
58	  { feature: "CRO pillars analyzed", starter: "7", growth: "7", pro: "7", agency: "7" },
59	  { feature: "Suggestions per scan", starter: "All", growth: "All", pro: "All", agency: "All" },
60	  { feature: "AI copy rewrites", starter: false, growth: true, pro: true, agency: true },
61	  { feature: "PDF report export", starter: "Basic", growth: "Branded", pro: "Branded", agency: "White-label" },
62	  { feature: "Competitive benchmarking", starter: false, growth: true, pro: true, agency: true },
63	  { feature: "Monthly score monitoring", starter: false, growth: true, pro: true, agency: true },
64	  { feature: "Team workspaces", starter: false, growth: false, pro: "3 seats", agency: "10 seats" },
65	  { feature: "REST API access", starter: false, growth: false, pro: true, agency: true },
66	  { feature: "Analytics integrations", starter: false, growth: false, pro: true, agency: true },
67	  { feature: "White-label reports", starter: false, growth: false, pro: false, agency: true },
68	  { feature: "Bulk URL processing", starter: false, growth: false, pro: false, agency: true },
69	  { feature: "Client portal", starter: false, growth: false, pro: false, agency: true },
70	  { feature: "Support response time", starter: "48 hours", growth: "24 hours", pro: "< 4 hours", agency: "< 2 hours" },
71	];
72	
73	const PLAN_NAMES: Record<PlanType, string> = {
74	  free: "Free",
75	  starter: "Starter",
76	  growth: "Growth",
77	  pro: "Pro",
78	  agency: "Agency",
79	};
80	
81	// Resolve the CTA label based on current plan vs tier
82	function getCtaLabel(
83	  tierPlan: PlanType,
84	  currentPlan: PlanType | null,
85	  defaultLabel: string
86	): string {
87	  if (!currentPlan) return defaultLabel;
88	  if (currentPlan === tierPlan) return "Current Plan";
89	  if (tierPlan === "free") return "Downgrade to Free";
90	
91	  const planOrder: PlanType[] = ["free", "starter", "growth", "pro", "agency"];
92	  const currentIndex = planOrder.indexOf(currentPlan);
93	  const tierIndex = planOrder.indexOf(tierPlan);
94	
95	  if (tierIndex > currentIndex) return `Upgrade to ${PLAN_NAMES[tierPlan]}`;
96	  return `Switch to ${PLAN_NAMES[tierPlan]}`;
97	}
98	
99	const Pricing = () => {
100	  const [isAnnual, setIsAnnual] = useState(false);
101	  const navigate = useNavigate();
102	  const { profile } = useAuth();
103	  const checkout = useCheckout();
104	  const portal = useCustomerPortal();
105	
106	  const currentPlan = profile?.plan ?? null;
107	  const billingCycle = isAnnual ? "annual" : "monthly";
108	
109	  function handleCta(tierPlan: PlanType) {
110	    if (!profile) {
111	      // Not logged in — send to signup
112	      navigate("/auth");
113	      return;
114	    }
115	
116	    if (tierPlan === "free" || tierPlan === currentPlan) {
117	      // Downgrading to free or managing current plan — send to portal
118	      portal.mutate();
119	      return;
120	    }
121	
122	    // Upgrade or switch plan
123	    checkout.mutate({
124	      plan: tierPlan as Exclude<PlanType, "free">,
125	      billingCycle,
126	    });
127	  }
128	
129	  return (
130	    <PageTransition>
131	      <div className="space-y-12">
132	        {/* Header */}
133	        <div className="text-center">
134	          <h2 className="text-3xl font-bold tracking-tight text-foreground">
135	            Pick the plan that fits your workflow
136	          </h2>
137	          <p className="mt-2 text-muted-foreground">
138	            Free to start. Upgrade when your page count grows. Cancel anytime.
139	          </p>
140	
141	          <div className="mt-6 flex items-center justify-center gap-3">
142	            <Label htmlFor="billing-toggle" className={cn("text-sm", !isAnnual && "font-semibold text-foreground")}>
143	              Monthly
144	            </Label>
145	            <Switch id="billing-toggle" checked={isAnnual} onCheckedChange={setIsAnnual} />
146	            <Label htmlFor="billing-toggle" className={cn("text-sm", isAnnual && "font-semibold text-foreground")}>
147	              Annual
148	            </Label>
149	            {isAnnual && (
150	              <Badge className="bg-green-50 text-green-700 border-green-200 text-xs">
151	                Save 20%
152	              </Badge>
153	            )}
154	          </div>
155	        </div>
156	
157	        {/* Pricing Cards */}
158	        <div className="mx-auto grid max-w-5xl grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
159	          {PRICING_TIERS.map((tier) => {
160	            const price = isAnnual ? tier.price_annual : tier.price_monthly;
161	            const isCurrentPlan = currentPlan === tier.plan;
162	            const isPaidPlan = tier.plan !== "free";
163	            const isCheckoutPending =
164	              checkout.isPending &&
165	              checkout.variables?.plan === tier.plan;
166	            const isPortalPending =
167	              portal.isPending &&
168	              (isCurrentPlan || tier.plan === "free");
169	
170	            const ctaLabel = profile
171	              ? getCtaLabel(tier.plan, currentPlan, tier.cta_text)
172	              : tier.cta_text;
173	
174	            const isPending = isCheckoutPending || isPortalPending;
175	
176	            return (
177	              <Card
178	                key={tier.plan}
179	                className={cn(
180	                  "relative border-border/40 shadow-soft hover:shadow-soft-lg hover:-translate-y-1 transition-all duration-300",
181	                  tier.highlighted &&
182	                    "border-primary ring-2 ring-primary/20 sm:scale-[1.02] shadow-lg shadow-primary/10"
183	                )}
184	              >
185	                {tier.highlighted && (
186	                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
187	                    <Badge className="bg-primary text-primary-foreground px-3 py-1 text-xs font-semibold">
188	                      <Zap className="mr-1 h-3 w-3" />
189	                      Most Popular
190	                    </Badge>
191	                  </div>
192	                )}
193	                {isCurrentPlan && (
194	                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
195	                    <Badge variant="outline" className="bg-card px-3 py-1 text-xs font-semibold border-border">
196	                      Your Plan
197	                    </Badge>
198	                  </div>
199	                )}
200	                <CardHeader className="text-center pb-2 pt-8">
201	                  <CardTitle className={cn("text-lg font-semibold", tier.highlighted ? "text-primary" : "text-foreground")}>
202	                    {tier.name}
203	                  </CardTitle>
204	                  <CardDescription className="text-sm">{tier.subtitle}</CardDescription>
205	                </CardHeader>
206	                <CardContent className="text-center">
207	                  <div className="mb-1">
208	                    <span className="text-4xl font-semibold leading-none text-foreground tabular-nums">
209	                      ${price}
210	                    </span>
211	                    <span className="text-muted-foreground">/mo</span>
212	                  </div>
213	                  {isAnnual && tier.price_monthly > 0 && (
214	                    <p className="mb-4 text-xs text-muted-foreground">
215	                      Billed as ${price * 12}/year &middot; was ${tier.price_monthly * 12}/year
216	                    </p>
217	                  )}
218	                  {!isAnnual && <p className="mb-4 text-xs text-muted-foreground">{tier.limits}</p>}
219	
220	                  {isCurrentPlan && isPaidPlan ? (
221	                    <Button
222	                      className="w-full rounded-lg"
223	                      variant="outline"
224	                      disabled={portal.isPending}
225	                      onClick={() => portal.mutate()}
226	                    >
227	                      {portal.isPending ? (
228	                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Opening portal...</>
229	                      ) : (
230	                        "Manage Subscription"
231	                      )}
232	                    </Button>
233	                  ) : (
234	                    <Button
235	                      className={cn("w-full rounded-lg", !tier.highlighted && "bg-card border border-border/50 text-foreground hover:bg-muted/50")}
236	                      variant={tier.highlighted ? "default" : "outline"}
237	                      disabled={isPending || isCurrentPlan}
238	                      onClick={() => handleCta(tier.plan)}
239	                    >
240	                      {isPending ? (
241	                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Redirecting...</>
242	                      ) : (
243	                        ctaLabel
244	                      )}
245	                    </Button>
246	                  )}
247	
248	                  <ul className="mt-6 space-y-3 text-left">
249	                    <TooltipProvider delayDuration={300}>
250	                      {tier.features.map((feature, i) => (
251	                        <li key={i} className="flex items-start gap-2.5">
252	                          {feature.included ? (
253	                            <Check className="mt-0.5 h-4 w-4 shrink-0 text-green-500" />
254	                          ) : (
255	                            <X className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground/40" />
256	                          )}
257	                          <span className={cn("text-sm", feature.included ? "text-foreground" : "text-muted-foreground")}>
258	                            {feature.text}
259	                          </span>
260	                          {feature.tooltip && (
261	                            <Tooltip>
262	                              <TooltipTrigger asChild>
263	                                <HelpCircle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-muted-foreground/40 cursor-help" />
264	                              </TooltipTrigger>
265	                              <TooltipContent side="top"><p className="text-xs">{feature.tooltip}</p></TooltipContent>
266	                            </Tooltip>
267	                          )}
268	                        </li>
269	                      ))}
270	                    </TooltipProvider>
271	                  </ul>
272	                </CardContent>
273	              </Card>
274	            );
275	          })}
276	        </div>
277	
278	        {/* Trust badges */}
279	        <div className="flex flex-wrap items-center justify-center gap-6 text-xs text-muted-foreground">
280	          {[
281	            { icon: Shield, text: "256-bit SSL encrypted" },
282	            { icon: Shield, text: "SOC 2 compliant infrastructure" },
283	            { icon: Shield, text: "GDPR compliant" },
284	            { icon: Shield, text: "30-day money-back guarantee" },
285	          ].map((badge) => (
286	            <span key={badge.text} className="flex items-center gap-1.5">
287	              <badge.icon className="h-3.5 w-3.5 text-muted-foreground" />
288	              {badge.text}
289	            </span>
290	          ))}
291	        </div>
292	
293	        <Separator />
294	
295	        {/* Feature Comparison Table */}
296	        <div className="mx-auto max-w-4xl">
297	          <h3 className="mb-6 text-center text-xl font-bold text-foreground">Feature comparison</h3>
298	          <div className="overflow-x-auto">
299	            <table className="w-full min-w-[700px] text-sm">
300	              <thead>
301	                <tr className="border-b border-border/50">
302	                  <th className="pb-3 text-left font-medium text-muted-foreground">Feature</th>
303	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Starter</th>
304	                  <th className="pb-3 text-center font-semibold text-primary w-24">Growth</th>
305	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Pro</th>
306	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Agency</th>
307	                </tr>
308	              </thead>
309	              <tbody>
310	                {COMPARISON_ROWS.map((row) => (
311	                  <tr key={row.feature} className="border-b border-border/40">
312	                    <td className="py-3 text-foreground">{row.feature}</td>
313	                    {[row.starter, row.growth, row.pro, row.agency].map((val, i) => (
314	                      <td key={i} className="py-3 text-center">
315	                        {val === true ? (
316	                          <Check className="mx-auto h-4 w-4 text-green-500" />
317	                        ) : val === false ? (
318	                          <X className="mx-auto h-4 w-4 text-muted-foreground/40" />
319	                        ) : (
320	                          <span className={cn("text-xs", i === 1 ? "font-semibold text-primary" : "text-foreground/80")}>
321	                            {val}
322	                          </span>
323	                        )}
324	                      </td>
325	                    ))}
326	                  </tr>
327	                ))}
328	              </tbody>
329	            </table>
330	          </div>
331	        </div>
332	
333	        <Separator />
334	
335	        {/* FAQ */}
336	        <div className="mx-auto max-w-2xl">
337	          <h3 className="mb-6 text-center text-xl font-bold text-foreground">
338	            Common questions
339	          </h3>
340	          <Accordion type="single" collapsible className="w-full">
341	            {FAQ_ITEMS.map((item, i) => (
342	              <AccordionItem key={i} value={`faq-${i}`}>
343	                <AccordionTrigger className="text-sm font-medium text-foreground hover:text-primary text-left">
344	                  {item.q}
345	                </AccordionTrigger>
346	                <AccordionContent className="text-sm text-muted-foreground leading-relaxed">
347	                  {item.a}
348	                </AccordionContent>
349	              </AccordionItem>
350	            ))}
351	          </Accordion>
352	        </div>
353	      </div>
354	    </PageTransition>
355	  );
356	};
357	
358	export default Pricing;
