1	import { useEffect } from "react";
2	import { useNavigate, useParams } from "react-router-dom";
3	import { Loader2, CheckCircle, AlertCircle } from "lucide-react";
4	import { Button } from "@/components/ui/button";
5	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
6	import { useAuth } from "@/contexts/AuthContext";
7	import { useAcceptInvite } from "@/hooks/use-teams";
8	
9	export default function AcceptInvite() {
10	  const { token } = useParams<{ token: string }>();
11	  const navigate = useNavigate();
12	  const { user, loading: authLoading, switchTeam } = useAuth();
13	  const acceptInvite = useAcceptInvite();
14	
15	  useEffect(() => {
16	    // Wait until auth is resolved and token is present
17	    if (authLoading || !token) return;
18	
19	    // Not logged in — redirect to login with return path
20	    if (!user) {
21	      navigate(`/login?redirect=/invite/${token}`);
22	      return;
23	    }
24	
25	    acceptInvite.mutate(token, {
26	      onSuccess: (data) => {
27	        switchTeam(data.team_id);
28	        navigate(`/team/${data.team_id}`);
29	      },
30	    });
31	  // eslint-disable-next-line react-hooks/exhaustive-deps
32	  }, [authLoading, user, token]);
33	
34	  if (authLoading || acceptInvite.isPending) {
35	    return (
36	      <div className="flex min-h-screen items-center justify-center">
37	        <Card className="w-full max-w-sm text-center">
38	          <CardHeader>
39	            <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
40	            <CardTitle className="text-base mt-3">Accepting invitation…</CardTitle>
41	          </CardHeader>
42	        </Card>
43	      </div>
44	    );
45	  }
46	
47	  if (acceptInvite.isSuccess) {
48	    return (
49	      <div className="flex min-h-screen items-center justify-center">
50	        <Card className="w-full max-w-sm text-center">
51	          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
52	            <CheckCircle className="h-10 w-10 text-emerald-500" />
53	            <p className="font-semibold">You have joined the team!</p>
54	            <Button size="sm" onClick={() => navigate("/dashboard")}>
55	              Go to Dashboard
56	            </Button>
57	          </CardContent>
58	        </Card>
59	      </div>
60	    );
61	  }
62	
63	  if (acceptInvite.isError) {
64	    const msg =
65	      acceptInvite.error instanceof Error
66	        ? acceptInvite.error.message
67	        : "The invitation may have expired or already been used.";
68	
69	    return (
70	      <div className="flex min-h-screen items-center justify-center px-4">
71	        <Card className="w-full max-w-sm text-center">
72	          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
73	            <AlertCircle className="h-10 w-10 text-red-500" />
74	            <p className="font-semibold text-foreground">Invitation invalid</p>
75	            <p className="text-sm text-muted-foreground">{msg}</p>
76	            <Button size="sm" onClick={() => navigate("/dashboard")}>
77	              Go to Dashboard
78	            </Button>
79	          </CardContent>
80	        </Card>
81	      </div>
82	    );
83	  }
84	
85	  return null;
86	}
