function CopyInline({ text }: { text: string }) {
  const [copied, setCopied] = useState(false)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current) }, [])

  const handleCopy = async () => {
    if (timerRef.current) clearTimeout(timerRef.current)
    try { await navigator.clipboard.writeText(text) } catch { /* fallback */ }
    setCopied(true)
    timerRef.current = setTimeout(() => setCopied(false), 2000)
  }
  return (
    <button
      onClick={handleCopy}
      className={cn(
        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
        copied
          ? "bg-green-50 text-green-600 border-green-200"
          : "bg-card text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
      )}
    >
      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
    </button>
  )
}

interface FindingCardProps {
