            "inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
            getEffortColor(finding.effort)
          )}>
            <Zap className="h-2.5 w-2.5" />
            {getEffortLabel(finding.effort)}
          </span>
          {finding.estimated_lift && finding.estimated_lift !== "0%" && (
            <span className="inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
              <TrendingUp className="h-2.5 w-2.5" />
