                    <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
                      <Lock className="h-4 w-4 text-indigo-500" />
                      <Button
                        asChild
                        size="sm"
                        className="h-7 rounded-lg bg-indigo-600 px-3 text-xs text-white hover:bg-indigo-700"
                      >
                        <Link href="/pricing">Upgrade to Pro</Link>
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Meta */}
            <div className={cn("flex items-center gap-3 text-xs text-muted-foreground", isFixed && "opacity-60")}>
              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
              <span>&middot;</span>
              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
                <>
                  <span>&middot;</span>
                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
                </>
              )}
            </div>

            {/* Mark as Fixed */}
            {scanResultId && onToggleFixed && (
              <div className="pt-1">
                {isFixed ? (
                  <Button
                    size="sm"
                    onClick={() => onToggleFixed(finding.id, true)}
                    className="h-8 rounded-lg bg-green-600 px-3 text-xs font-medium text-white hover:bg-green-700"
                  >
                    <CheckCircle2 className="mr-1.5 h-3.5 w-3.5" />
                    Fixed
                  </Button>
                ) : (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={() => onToggleFixed(finding.id, false)}
                    className="h-8 rounded-lg border-border/50 px-3 text-xs font-medium text-muted-foreground hover:border-green-500 hover:text-green-700"
                  >
                    <CheckCircle2 className="mr-1.5 h-3.5 w-3.5" />
                    Mark as Fixed
                  </Button>
                )}
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  )

  if (finding.is_premium) {
    return <PremiumLock>{content}</PremiumLock>
  }

  return content
}

