export default function PublicReportPage() {
  const params = useParams<{ token: string }>()
  const token = params.token
  const { data, isLoading, error } = usePublicScan(token ?? "")

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background">
        <PublicHeader teamBranding={null} />
        <main className="mx-auto max-w-4xl px-4 py-10 sm:px-6 lg:px-8">
          <PublicReportSkeleton />
        </main>
      </div>
    )
  }

  if (error || !data) {
    const isNotFound = error instanceof Error && error.message === "NOT_FOUND"
    return (
      <div className="min-h-screen bg-background">
        <PublicHeader teamBranding={null} />
        <main className="mx-auto max-w-4xl px-4 py-20 sm:px-6 lg:px-8">
          <div className="flex flex-col items-center text-center">
            <div className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl bg-muted/50">
              <AlertCircle className="h-8 w-8 text-muted-foreground" />
            </div>
            <h2 className="text-xl font-bold text-foreground">
              {isNotFound ? "Report not found" : "Something went wrong"}
            </h2>
            <p className="mt-2 max-w-sm text-sm text-muted-foreground">
              {isNotFound
                ? "This report link may have expired or been revoked by its owner."
                : "We couldn't load this report. Please try again later."}
            </p>
            <Button asChild className="mt-6">
              <Link href="/">Go to ConvertScan</Link>
            </Button>
          </div>
        </main>
      </div>
    )
  }

  const { scan, results, teamBranding } = data
  const score = scan.overall_score ?? 0
  const percentile = getPercentileRank(score)
  const scoreLabel = getScoreLabel(score)
  const allFindings = results.flatMap((r) => r.findings)
  const criticalCount = allFindings.filter((f) => f.severity === "critical").length
  const sortedPillars = [...results].sort((a, b) => a.score - b.score)

  const brandStyle: CSSProperties = teamBranding?.brand_color
    ? ({ "--brand-accent": teamBranding.brand_color } as CSSProperties)
    : {}

  return (
    <div className="min-h-screen bg-background" style={brandStyle}>
      <PublicHeader teamBranding={teamBranding} />

      <main className="mx-auto max-w-4xl px-4 py-10 sm:px-6 lg:px-8 space-y-8">
        {/* Report title */}
        <div className="space-y-2">
          <h1 className="text-3xl font-bold tracking-tight text-foreground">
            {scan.page_title ?? "CRO Audit Report"}
          </h1>
          <div className="flex flex-wrap items-center gap-3 text-sm text-muted-foreground">
            <div className="flex items-center gap-1.5">
              <Globe className="h-3.5 w-3.5" />
              <a
                href={scan.url}
                target="_blank"
                rel="noopener noreferrer"
                className="text-primary hover:underline truncate max-w-xs"
              >
                {scan.url}
              </a>
            </div>
            {scan.completed_at && (
              <>
                <Separator orientation="vertical" className="h-3.5" />
                <div className="flex items-center gap-1.5">
                  <Calendar className="h-3.5 w-3.5" />
                  {formatDate(scan.completed_at)}
                </div>
              </>
            )}
            <Badge variant="outline" className="text-xs capitalize">
              {scan.page_type} page
            </Badge>
          </div>
        </div>

        {/* Score hero */}
        <Card className={cn("border-border/50 shadow-none overflow-hidden", getScoreBgLight(score))}>
          <CardContent className="p-8">
            <div className="flex flex-col items-center gap-6 sm:flex-row sm:items-center">
              <ScoreRing score={score} size={180} strokeWidth={12} />
              <div className="text-center sm:text-left space-y-2">
                <h2 className="text-2xl font-bold text-foreground">
                  CRO Score: <span className={getScoreColor(score)}>{score}/100</span>
                </h2>
                <p className="text-sm font-medium text-foreground">
                  Rating: <span className="font-bold">{scoreLabel}</span>
                </p>
                <p className="text-sm text-muted-foreground">
                  Better than <span className={cn("font-bold", getScoreColor(score))}>{percentile}%</span> of pages analyzed
                </p>
                <div className="flex flex-wrap items-center justify-center gap-3 pt-1 sm:justify-start">
                  <Badge variant="outline" className="text-xs">
                    {results.length} pillars analyzed
                  </Badge>
                  {criticalCount > 0 && (
                    <Badge variant="outline" className="border-red-200 bg-red-50 text-red-700 text-xs">
                      {criticalCount} critical issues
                    </Badge>
                  )}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Pillar grid */}
        {results.length > 0 && (
          <div>
            <h3 className="mb-4 text-base font-semibold text-foreground">Pillar Breakdown</h3>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {sortedPillars.map((result) => (
                <PillarSummaryCard key={result.pillar} result={result} />
              ))}
            </div>
          </div>
        )}

        {/* Findings */}
        {allFindings.length > 0 && (
          <div>
            <Card className="border-border/50 shadow-none">
              <CardHeader>
                <CardTitle className="text-base font-semibold">Key Findings</CardTitle>
                <p className="text-sm text-muted-foreground">
                  {allFindings.length} issues found across {results.length} CRO pillars
                </p>
              </CardHeader>
              <CardContent className="space-y-4">
                {sortedPillars.map((result) => {
                  const pillarConfig = CRO_PILLARS.find((p) => p.key === result.pillar)
                  const visibleFindings = result.findings.filter((f) => !f.is_premium)
                  if (visibleFindings.length === 0) return null
                  return (
                    <div key={result.pillar} className="space-y-3">
                      <div className="flex items-center gap-2">
                        {pillarConfig && (
                          <pillarConfig.icon className="h-4 w-4 text-muted-foreground" />
                        )}
                        <h4 className="text-sm font-semibold text-foreground">
                          {pillarConfig?.label ?? result.pillar}
                        </h4>
                        <span className={cn("text-sm font-bold tabular-nums", getScoreColor(result.score))}>
                          {result.score}/100
                        </span>
                      </div>
                      {visibleFindings.map((finding) => (
                        <FindingCard key={finding.id} finding={finding} />
                      ))}
                    </div>
                  )
                })}
              </CardContent>
            </Card>
          </div>
        )}

        {/* CTA */}
        <CTABanner teamBranding={teamBranding} />
      </main>

      {/* Footer */}
      <footer className="border-t border-border/40 py-6 text-center text-xs text-muted-foreground">
        {teamBranding ? (
          <p>
            Report prepared by{" "}
            <span className="font-medium text-foreground">{teamBranding.name}</span>
            {" — "}
            <a href="/" className="text-primary hover:underline">
              Powered by ConvertScan
            </a>
          </p>
        ) : (
          <p>
            This report was generated by{" "}
            <a href="/" className="text-primary hover:underline">
              ConvertScan
            </a>
            {" "}— AI-powered CRO audit tool
          </p>
        )}
      </footer>
    </div>
  )
}

'use client'

import { useEffect } from "react"
import { useParams, useRouter } from "next/navigation"
import { Loader2, CheckCircle, AlertCircle } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { useAuth } from "@/contexts/AuthContext"
import { useAcceptInvite } from "@/hooks/use-teams"

export default function AcceptInvitePage() {
  const params = useParams<{ token: string }>()
  const token = params.token
  const router = useRouter()
  const { user, loading: authLoading, switchTeam } = useAuth()
  const acceptInvite = useAcceptInvite()

  useEffect(() => {
    if (authLoading || !token) return

    if (!user) {
      router.push(`/login?redirect=/invite/${token}`)
      return
    }

    acceptInvite.mutate(token, {
      onSuccess: (data) => {
        switchTeam(data.team_id)
        router.push(`/team/${data.team_id}`)
      },
    })
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authLoading, user, token])

  if (authLoading || acceptInvite.isPending) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Card className="w-full max-w-sm text-center">
          <CardHeader>
            <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
            <CardTitle className="text-base mt-3">Accepting invitation&hellip;</CardTitle>
          </CardHeader>
        </Card>
      </div>
    )
  }

  if (acceptInvite.isSuccess) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Card className="w-full max-w-sm text-center">
          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
            <CheckCircle className="h-10 w-10 text-emerald-500" />
            <p className="font-semibold">You have joined the team!</p>
            <Button size="sm" onClick={() => router.push("/dashboard")}>
              Go to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (acceptInvite.isError) {
    const msg =
      acceptInvite.error instanceof Error
        ? acceptInvite.error.message
        : "The invitation may have expired or already been used."

    return (
      <div className="flex min-h-screen items-center justify-center px-4">
        <Card className="w-full max-w-sm text-center">
          <CardContent className="pt-8 pb-6 flex flex-col items-center gap-3">
            <AlertCircle className="h-10 w-10 text-red-500" />
            <p className="font-semibold text-foreground">Invitation invalid</p>
            <p className="text-sm text-muted-foreground">{msg}</p>
            <Button size="sm" onClick={() => router.push("/dashboard")}>
              Go to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    )
  }

  return null
}

