23	export function useGenerateShareLink() {
24	  const queryClient = useQueryClient();
25	
26	  return useMutation({
27	    mutationFn: async (scanId: string): Promise<string> => {
28	      const token = crypto.randomUUID();
29	      const { error } = await supabase
30	        .from("scans")
31	        .update({ share_token: token, is_public: true })
32	        .eq("id", scanId);
33	
34	      if (error) throw new Error(error.message);
35	
36	      return `${window.location.origin}/r/${token}`;
37	    },
38	    onSuccess: (_url, scanId) => {
39	      // Invalidate so useScan refetches updated share_token + is_public
40	      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
41	      queryClient.invalidateQueries({ queryKey: ["scans"] });
42	    },
43	  });
44	}
