47	
48	export function useRevokeShareLink() {
49	  const queryClient = useQueryClient();
50	
51	  return useMutation({
52	    mutationFn: async (scanId: string): Promise<void> => {
53	      const { error } = await supabase
54	        .from("scans")
55	        .update({ share_token: null, is_public: false })
56	        .eq("id", scanId);
57	
58	      if (error) throw new Error(error.message);
59	    },
60	    onSuccess: (_data, scanId) => {
61	      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
62	      queryClient.invalidateQueries({ queryKey: ["scans"] });
63	    },
64	  });
65	}
