69	function dbFindingToFinding(f: DbFinding): Finding {
70	  return {
71	    id: f.id,
72	    title: f.title,
73	    severity: f.severity,
74	    current_state: f.current_state,
75	    recommendation: f.recommendation,
76	    ai_suggestion: f.ai_suggestion,
77	    is_premium: f.is_premium,
78	    effort: f.effort,
79	    estimated_lift: f.estimated_lift,
80	    category: f.category,
81	  };
82	}
