84	function rowToPillarResult(row: ScanResultRow): PillarResult {
85	  return {
86	    id: row.id,
87	    scan_id: row.scan_id,
88	    pillar: row.pillar,
89	    score: row.score,
90	    weight: row.weight,
91	    benchmark: row.benchmark,
92	    findings: (row.findings ?? []).map(dbFindingToFinding),
93	  };
94	}
