96	export function usePublicScan(token: string) {
97	  return useQuery({
98	    queryKey: shareReportKeys.publicScan(token),
99	    queryFn: async (): Promise<PublicScanPayload> => {
100	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
101	      const supabaseKey = (
102	        (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string | undefined) ??
103	        (import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined)
104	      );
105	
106	      if (!supabaseUrl || !supabaseKey) {
107	        throw new Error("Missing Supabase environment variables");
108	      }
109	
110	      const res = await fetch(
111	        `${supabaseUrl}/functions/v1/public-report?token=${encodeURIComponent(token)}`,
112	        {
113	          headers: {
114	            apikey: supabaseKey,
115	            "Content-Type": "application/json",
116	          },
117	        }
118	      );
119	
120	      if (res.status === 404) {
121	        throw new Error("NOT_FOUND");
122	      }
123	
124	      if (!res.ok) {
125	        throw new Error(`Failed to load public report: ${res.status}`);
126	      }
127	
128	      const json = (await res.json()) as {
129	        scan: Omit<Scan, "user_id">;
130	        results: ScanResultRow[];
131	        teamBranding?: TeamBranding;
132	      };
133	
134	      return {
135	        scan: json.scan,
136	        results: json.results.map(rowToPillarResult),
137	        teamBranding: json.teamBranding ?? null,
138	      };
139	    },
140	    enabled: !!token,
141	    staleTime: 1000 * 60 * 5,
142	    retry: (failureCount, error) => {
143	      if (error instanceof Error && error.message === "NOT_FOUND") return false;
144	      return failureCount < 2;
145	    },
146	  });
147	}
