import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import supabase from "@/lib/supabase"
import type { PillarResult, Scan, TeamBranding } from "@/types"
import type { DbFinding, ScanResultRow } from "@/types/database"
import type { Finding } from "@/types"

// ── Query keys ──────────────────────────────────────────────────

export const shareReportKeys = {
  publicScan: (token: string) => ["public-scan", token] as const,
}

// ── Public report payload shape (from edge function) ────────────

export interface PublicScanPayload {
  scan: Omit<Scan, "user_id">
  results: PillarResult[]
  teamBranding: TeamBranding | null
}

// ── useGenerateShareLink ────────────────────────────────────────

export function useGenerateShareLink() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (scanId: string): Promise<string> => {
      const token = crypto.randomUUID()
      const { error } = await supabase
        .from("scans")
        .update({ share_token: token, is_public: true })
        .eq("id", scanId)

      if (error) throw new Error(error.message)

      return `${window.location.origin}/r/${token}`
    },
    onSuccess: (_url, scanId) => {
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] })
      queryClient.invalidateQueries({ queryKey: ["scans"] })
    },
  })
}

// ── useRevokeShareLink ──────────────────────────────────────────

export function useRevokeShareLink() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      const { error } = await supabase
        .from("scans")
        .update({ share_token: null, is_public: false })
        .eq("id", scanId)

      if (error) throw new Error(error.message)
    },
    onSuccess: (_data, scanId) => {
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] })
      queryClient.invalidateQueries({ queryKey: ["scans"] })
    },
  })
}

// ── usePublicScan ───────────────────────────────────────────────

function dbFindingToFinding(f: DbFinding): Finding {
  return {
    id: f.id,
    title: f.title,
    severity: f.severity,
    current_state: f.current_state,
    recommendation: f.recommendation,
    ai_suggestion: f.ai_suggestion,
    is_premium: f.is_premium,
    effort: f.effort,
    estimated_lift: f.estimated_lift,
    category: f.category,
  }
}

function rowToPillarResult(row: ScanResultRow): PillarResult {
  return {
    id: row.id,
    scan_id: row.scan_id,
    pillar: row.pillar,
    score: row.score,
    weight: row.weight,
    benchmark: row.benchmark,
    findings: (row.findings ?? []).map(dbFindingToFinding),
  }
}

export function usePublicScan(token: string) {
  return useQuery({
    queryKey: shareReportKeys.publicScan(token),
    queryFn: async (): Promise<PublicScanPayload> => {
      const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
      const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

      if (!supabaseUrl || !supabaseKey) {
        throw new Error("Missing Supabase environment variables")
      }

      const res = await fetch(
        `${supabaseUrl}/functions/v1/public-report?token=${encodeURIComponent(token)}`,
        {
          headers: {
            apikey: supabaseKey,
            "Content-Type": "application/json",
          },
        }
      )

      if (res.status === 404) {
        throw new Error("NOT_FOUND")
      }

      if (!res.ok) {
        throw new Error(`Failed to load public report: ${res.status}`)
      }

      const json = (await res.json()) as {
        scan: Omit<Scan, "user_id">
        results: ScanResultRow[]
        teamBranding?: TeamBranding
      }

      return {
        scan: json.scan,
        results: json.results.map(rowToPillarResult),
        teamBranding: json.teamBranding ?? null,
      }
    },
    enabled: !!token,
    staleTime: 1000 * 60 * 5,
    retry: (failureCount, error) => {
      if (error instanceof Error && error.message === "NOT_FOUND") return false
      return failureCount < 2
    },
  })
}

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { toast } from "sonner"
import supabase from "@/lib/supabase"
import { useAuth } from "@/contexts/AuthContext"
import type { Team, TeamMember, TeamInvite } from "@/types/index"
import type { TeamRow, TeamMemberRow, TeamInviteRow } from "@/types/database"

// ── Query keys ──────────────────────────────────────────────────

export const teamKeys = {
  all: ["teams"] as const,
  lists: () => [...teamKeys.all, "list"] as const,
  list: (userId: string) => [...teamKeys.lists(), userId] as const,
  details: () => [...teamKeys.all, "detail"] as const,
  detail: (id: string) => [...teamKeys.details(), id] as const,
  members: (teamId: string) => [...teamKeys.all, "members", teamId] as const,
  invites: (teamId: string) => [...teamKeys.all, "invites", teamId] as const,
}

// ── Row → App type mappers ───────────────────────────────────────

function rowToTeam(row: TeamRow): Team {
  return {
    id: row.id,
    name: row.name,
    owner_id: row.owner_id,
    logo_url: row.logo_url,
    brand_color: row.brand_color,
    custom_domain: row.custom_domain,
    created_at: row.created_at,
  }
}

interface TeamMemberRowWithProfile extends TeamMemberRow {
  profiles?: {
    full_name: string
    email: string
    avatar_url: string | null
  } | null
}

function rowToTeamMember(row: TeamMemberRowWithProfile): TeamMember {
  return {
    id: row.id,
    team_id: row.team_id,
    user_id: row.user_id,
    role: row.role,
    joined_at: row.joined_at,
    profile: row.profiles
      ? {
          full_name: row.profiles.full_name,
          email: row.profiles.email,
          avatar_url: row.profiles.avatar_url,
        }
      : undefined,
  }
}

function rowToTeamInvite(row: TeamInviteRow): TeamInvite {
  return {
    id: row.id,
    team_id: row.team_id,
    email: row.email,
    role: row.role,
    token: row.token,
    expires_at: row.expires_at,
    created_at: row.created_at,
  }
}

// ── useTeams ─────────────────────────────────────────────────────

export function useTeams() {
  const { user } = useAuth()

  return useQuery({
    queryKey: teamKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Team[]> => {
      if (!user?.id) return []

      const { data, error } = await supabase
        .from("team_members")
        .select("team_id, teams(*)")
        .eq("user_id", user.id)
        .order("joined_at", { ascending: true })

      if (error) throw new Error(error.message)

      return (data ?? [])
        .map((row) => {
          const team = (row as { team_id: string; teams: TeamRow | null }).teams
          return team ? rowToTeam(team) : null
        })
        .filter((t): t is Team => t !== null)
    },
    enabled: !!user?.id,
  })
}

// ── useTeam ──────────────────────────────────────────────────────

export function useTeam(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.detail(teamId ?? ""),
    queryFn: async (): Promise<Team | null> => {
      if (!teamId) return null

      const { data, error } = await supabase
        .from("teams")
        .select("*")
        .eq("id", teamId)
        .single()

      if (error) {
        if (error.code === "PGRST116") return null
        throw new Error(error.message)
      }

      return rowToTeam(data as TeamRow)
    },
    enabled: !!teamId,
  })
}

// ── useTeamMembers ───────────────────────────────────────────────

export function useTeamMembers(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.members(teamId ?? ""),
    queryFn: async (): Promise<TeamMember[]> => {
      if (!teamId) return []

      const { data, error } = await supabase
        .from("team_members")
        .select("*, profiles(full_name, email, avatar_url)")
        .eq("team_id", teamId)
        .order("joined_at", { ascending: true })

      if (error) throw new Error(error.message)

      return (data as TeamMemberRowWithProfile[]).map(rowToTeamMember)
    },
    enabled: !!teamId,
  })
}

// ── useTeamInvites ───────────────────────────────────────────────

export function useTeamInvites(teamId: string | undefined) {
  return useQuery({
    queryKey: teamKeys.invites(teamId ?? ""),
    queryFn: async (): Promise<TeamInvite[]> => {
      if (!teamId) return []

      const { data, error } = await supabase
        .from("team_invites")
        .select("*")
        .eq("team_id", teamId)
        .gt("expires_at", new Date().toISOString())
        .order("created_at", { ascending: false })

      if (error) throw new Error(error.message)

      return (data as TeamInviteRow[]).map(rowToTeamInvite)
    },
    enabled: !!teamId,
  })
}

// ── useCreateTeam ────────────────────────────────────────────────

export function useCreateTeam() {
  const { user } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (name: string): Promise<Team> => {
      if (!user?.id) throw new Error("Not authenticated")

      const { data: teamData, error: teamError } = await supabase
        .from("teams")
        .insert({ name, owner_id: user.id })
        .select("*")
        .single()

      if (teamError) throw new Error(teamError.message)

      const team = rowToTeam(teamData as TeamRow)

      const { error: memberError } = await supabase
        .from("team_members")
        .insert({ team_id: team.id, user_id: user.id, role: "owner" })

      if (memberError) throw new Error(memberError.message)

      return team
    },
    onSuccess: (data) => {
      if (!user?.id) return
      queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
        prev ? [...prev, data] : [data]
      )
      queryClient.setQueryData(teamKeys.detail(data.id), data)
      toast.success(`Team "${data.name}" created`)
    },
    onError: (err: Error) => {
      toast.error(err.message)
    },
  })
}

// ── useUpdateTeam ────────────────────────────────────────────────

export function useUpdateTeam(teamId: string) {
  const { user } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (updates: {
      name?: string
      logo_url?: string | null
      brand_color?: string
      custom_domain?: string | null
    }): Promise<Team> => {
      const { data, error } = await supabase
        .from("teams")
        .update(updates)
        .eq("id", teamId)
        .select("*")
        .single()

      if (error) throw new Error(error.message)
      return rowToTeam(data as TeamRow)
    },
    onSuccess: (data) => {
      queryClient.setQueryData(teamKeys.detail(teamId), data)
      if (user?.id) {
        queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
          prev ? prev.map((t) => (t.id === teamId ? data : t)) : [data]
        )
      }
      toast.success("Team updated")
    },
    onError: (err: Error) => {
      toast.error(err.message)
    },
  })
}

// ── useDeleteTeam ────────────────────────────────────────────────

export function useDeleteTeam() {
  const { user } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (teamId: string): Promise<void> => {
      const { error } = await supabase.from("teams").delete().eq("id", teamId)
      if (error) throw new Error(error.message)
    },
    onSuccess: (_data, teamId) => {
      if (!user?.id) return
      queryClient.setQueryData<Team[]>(teamKeys.list(user.id), (prev) =>
        prev ? prev.filter((t) => t.id !== teamId) : []
      )
      queryClient.removeQueries({ queryKey: teamKeys.detail(teamId) })
      toast.success("Team deleted")
    },
    onError: (err: Error) => {
      toast.error(err.message)
    },
  })
}

// ── useInviteMember ──────────────────────────────────────────────

export function useInviteMember() {
  const { profile } = useAuth()
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({
      teamId,
      email,
      role,
    }: {
      teamId: string
      email: string
      role: string
    }): Promise<void> => {
      const { error } = await supabase.functions.invoke("team-invite", {
        body: {
          team_id: teamId,
          email,
          role,
          inviter_name: profile?.full_name ?? "A team member",
        },
      })

      if (error) throw new Error(error.message)
    },
    onSuccess: (_data, { teamId }) => {
      queryClient.invalidateQueries({ queryKey: teamKeys.invites(teamId) })
      toast.success("Invitation sent")
    },
    onError: (err: Error) => {
      toast.error(err.message)
    },
  })
}

// ── useRevokeInvite ──────────────────────────────────────────────

export function useRevokeInvite(teamId: string) {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (inviteId: string): Promise<void> => {
      const { error } = await supabase
        .from("team_invites")
        .delete()
        .eq("id", inviteId)
      if (error) throw new Error(error.message)
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: teamKeys.invites(teamId) })
      toast.success("Invite revoked")
    },
    onError: (err: Error) => {
      toast.error(err.message)
    },
  })
}

